<?php
require_once __DIR__ . '/../config/db.php';
$pdo=getPDO(); $id=$_GET['id'] ?? 0; $stmt=$pdo->prepare("SELECT po.*, p.title, s.supplier_name FROM purchase_orders po LEFT JOIN procurements p ON p.id=po.procurement_id LEFT JOIN suppliers s ON s.id=po.supplier_id WHERE po.id=?"); $stmt->execute([$id]); $po=$stmt->fetch(); if(!$po) die('Purchase order not found');
header('Content-Type: text/html; charset=UTF-8');
?><!doctype html><html><head><title>Purchase Order</title><style>body{font-family:Arial;margin:40px;line-height:1.6}.center{text-align:center}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><div class="center"><h2>Badulla Hospital</h2><h3>Purchase Order</h3></div><p><b>PO Number:</b> <?=htmlspecialchars($po['po_number'])?></p><p><b>Procurement:</b> <?=htmlspecialchars($po['title'])?></p><p><b>Supplier:</b> <?=htmlspecialchars($po['supplier_name'])?></p><p><b>Date:</b> <?=htmlspecialchars($po['po_date'])?></p><p><b>Amount:</b> Rs. <?=number_format((float)$po['amount'],2)?></p><p><b>Status:</b> <?=htmlspecialchars($po['status'])?></p><p><b>Remarks:</b><br><?=nl2br(htmlspecialchars($po['remarks'] ?? ''))?></p></body></html>
